 const listen=th.audio?`<div style="display:flex;align-items:center;gap:10px;margin-top:12px;padding-top:12px;border-top:1px solid var(--hl)"><span style="display:flex;color:var(--g)">${ic('headphones',18)}</span><span style="flex:1;min-width:0"><small style="margin:0">Listen during it</small><b style="font-weight:500;display:block">${esc(th.audio)}</b></span><a class=btn href="#/skill/${dow(D())}" style="margin:0;min-height:36px">Open</a></div>`:'';
 const today=tp[tn]?`<b style="font-size:22px;display:block;margin:2px 0">${esc(tn)}</b><small>${tp[tn].length} exercises${last?' · last time '+last.date:''}${mf?' · then '+fm('Mobility: '+tn)+' min mobility':''}</small><div style="display:flex;gap:6px;margin-top:10px"><button class="btn pri" data-a=start data-n="${esc(tn)}" style="margin:0;flex:1;justify-content:center">${ic('play')} Start ${esc(tn)}</button>${mf?`<button class=btn data-a=flowgo data-n="Mobility: ${esc(tn)}" style="margin:0">${ic('timer',16)} Mobility</button>`:''}</div>`
  :fl[tn]?`<b style="font-size:20px;display:block;margin:2px 0">${esc(tn)}</b><small>Timed workout · ${fm(tn)} min</small><button class="btn pri" data-a=flowgo data-n="${esc(tn)}" style="width:100%;justify-content:center;margin-top:10px">${ic('play')} Start ${esc(tn)}</button>`
  :tn==='Soccer match'?`<b style="font-size:22px;display:block;margin:2px 0">Soccer match</b>${so===2?`<small>${ic('check')} Played. Counts as this week's cardio.</small>`:`<button class="btn pri" data-a=socdone style="margin-top:10px">${ic('check')} Mark soccer played</button>`}`
  :`<b style="font-size:20px;display:block;margin:2px 0">${esc(tn||'Rest day')}</b><small>No workout planned. Pick one below if you want to train anyway.</small>`;
 let h=`<h1>Train</h1><div class=card style="border-left:4px solid var(--g)"><div style="display:flex;align-items:center;gap:10px">${box(tp[tn]?wIcon(tn):fl[tn]?'timer':'sun',tp[tn]?215:130)}<small style="margin:0">Today's session</small></div>${today}${tn&&tn!=='Rest'?listen:''}</div>`
 +secH('dumbbell','Strength workouts',`<small style="margin:0">sets, reps and weights</small>`)+`<div class=card style="padding:4px 12px">`+Object.keys(tp).map(n=>{const lg=S.log.filter(l=>l.tpl===n).pop();return row('start',n,wIcon(n),215,pill('list',tp[n].length+' exercises')+pill('calendar',lg?'last '+new Date(lg.date+'T12:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'not done yet'),n===tn)}).join('')+row('start','','plus',215,pill('list','add exercises as you go'),false).replace('border-bottom:1px solid var(--hl)','border-bottom:0')+`</div><small>Mobility for each workout is the last row inside it.</small>`
 +secH('timer','Timed workouts',`<a href="#/flows" style="font-size:13px">Edit</a>`)+`<div class=card style="padding:4px 12px">`+Object.keys(fl).map((n,k,a)=>row('flowgo',n,/Mobility/.test(n)?'leaf':'timer',/Mobility/.test(n)?170:130,pill('clock',fm(n)+' min')+pill('list',fl[n].length+' steps'),n===tn||n==='Mobility: '+tn).replace(k===a.length-1?'border-bottom:1px solid var(--hl)':'@@','border-bottom:0')).join('')+`</div>`
 +(NATIVE?secH('sliders','Settings')+fold('Timer alarm',({'':'Default',chime:'Chime',bell:'Bell',digital:'Digital'})[S.asnd||'']+(S.astep?' · every step':''),`<small>Sound when a rest timer ends, also in silent mode. Tap one to hear it.</small>${seg([['','Default'],['chime','Chime'],['bell','Bell'],['digital','Digital']],S.asnd||'','asnd')}<label style="display:flex;gap:10px;align-items:center;font-size:14px;margin-top:6px"><input type=checkbox data-c=astep ${S.astep?'checked':''} style="width:22px;height:22px;margin:0;flex:none"> Also ring for every step of a timed workout</label>`):'');
 const hist=S.log.slice(-15).reverse().map((l,i)=>{const sets=l.ex.reduce((a,e)=>a+e.s.length,0),vol=l.ex.reduce((a,e)=>a+e.s.reduce((b,s)=>b+(+s.w||0)*(+s.r||0),0),0);
 return`<details style="border-bottom:1px solid var(--hl);padding:8px 0"><summary><b>${esc(l.tpl)}</b> <small style="display:inline">${l.date} · ${l.dur} min · ${sets} sets · ${Math.round(vol)} kg</small></summary>${l.ex.map(e=>`<small>${esc(e.n)}: ${e.s.map(s=>s.w+'×'+s.r).join(', ')}</small>`).join('')}<button class=btn data-a=logdel data-i="${S.log.length-1-i}">Delete</button></details>`}).join('')||'<small>No workouts yet.</small>';
