 const PG=[['fuel','utensils','Diet and water','Tick meals, log water and steps'],['money','wallet','Budget','Income, expenses and buckets'],['skill','headphones','Audio and watch list','What you listen to each day'],['meaning','leaf','Reflect','Rate your day, gratitude and wins'],['week','chart','Weeks','Your log per day and week'],['todo','check','To-dos','Tasks with date, time and description']];
