 const tn=themeOf(t).train,did=S.log.some(l=>l.date===t)||(S.fl||[]).some(x=>x.d===t),bl=bwLast(),sm=wsum(weekStart(t)),refl=(S.nl.meaning||[]).some(e=>e.d===t),kt=+S.cfg.kcalT||0;
